// GENERATED by server/scripts/sync-shared.js from shared/ -- do not edit directly.
const { SPORT_KEYS } = require('./sports');

// Single source for match result + per-player stat rules. Pure functions, no I/O.
// Order of the defs below is the display order. `summary: true` = shown in the profile summary.
const def = (key, en, he, max, summary = false) => ({ key, en, he, max, summary });

const STAT_DEFS = {
  SOCCER: [
    def('goals', 'Goals', 'שערים', 30, true),
    def('assists', 'Assists', 'בישולים', 30, true),
    def('saves', 'Saves', 'הצלות', 100),
    def('cleanSheet', 'Clean sheet', 'רשת נקייה', 1),
    def('yellowCards', 'Yellow cards', 'כרטיסים צהובים', 2),
    def('redCards', 'Red cards', 'כרטיסים אדומים', 1),
    def('ownGoals', 'Own goals', 'שערים עצמיים', 10),
    def('mvp', 'MVP', 'שחקן המשחק', 1, true),
  ],
  BASKETBALL: [
    def('points', 'Points', 'נקודות', 200, true),
    def('rebounds', 'Rebounds', 'ריבאונדים', 60, true),
    def('assists', 'Assists', 'אסיסטים', 50, true),
    def('steals', 'Steals', 'חטיפות', 20),
    def('blocks', 'Blocks', 'חסימות', 20),
    def('threePointers', 'Three-pointers', 'שלשות', 30),
    def('fouls', 'Fouls', 'עבירות', 10),
    def('mvp', 'MVP', 'שחקן המשחק', 1, true),
  ],
  TENNIS: [
    def('aces', 'Aces', 'אייסים', 100, true),
    def('doubleFaults', 'Double faults', 'פסילות כפולות', 50),
    def('winners', 'Winners', 'וינרס', 200),
  ],
};

// Keys that count toward the team score, for the soft "player sum > team score" warning.
const SCORING_KEY = { SOCCER: 'goals', BASKETBALL: 'points' };
// Sanity cap on a team score.
const MAX_TEAM_SCORE = { SOCCER: 99, BASKETBALL: 300 };
const DEFAULT_TENNIS_BEST_OF = 3;

const isNonNegInt = (n) => typeof n === 'number' && Number.isInteger(n) && n >= 0;
const err = (code, extra) => ({ code, ...extra });
const badNumberCode = (v) => (typeof v === 'number' && v < 0 ? 'NEGATIVE' : 'NOT_INT');

function getStatDefs(sport) {
  return STAT_DEFS[sport] || [];
}

function getStatKeys(sport) {
  return getStatDefs(sport).map((d) => d.key);
}

function getSummaryKeys(sport) {
  return getStatDefs(sport).filter((d) => d.summary).map((d) => d.key);
}

function getStatLabel(sport, key, lang = 'en') {
  const d = getStatDefs(sport).find((x) => x.key === key);
  if (!d) return key;
  return lang === 'he' ? d.he : d.en;
}

/**
 * Validates one player's stats for a sport. Unknown keys, non-integers, negatives and
 * values above the sanity cap are errors. Returns `stats` = the valid entries only.
 */
function validateStats(sport, values) {
  const defs = STAT_DEFS[sport];
  if (!defs) return { valid: false, errors: [err('UNKNOWN_SPORT')], stats: {} };
  if (!values || typeof values !== 'object' || Array.isArray(values)) {
    return { valid: false, errors: [err('INVALID_STATS')], stats: {} };
  }
  const errors = [];
  const stats = {};
  for (const [key, value] of Object.entries(values)) {
    const d = defs.find((x) => x.key === key);
    if (!d) errors.push(err('UNKNOWN_KEY', { key }));
    else if (!isNonNegInt(value)) errors.push(err(badNumberCode(value), { key }));
    else if (value > d.max) errors.push(err('TOO_LARGE', { key, max: d.max }));
    else stats[key] = value;
  }
  return { valid: errors.length === 0, errors, stats };
}

/** WIN / LOSS / DRAW from one side's perspective. */
function deriveOutcome(sideScore, otherScore) {
  if (sideScore > otherScore) return 'WIN';
  if (sideScore < otherScore) return 'LOSS';
  return 'DRAW';
}

// A regular set: 6-0..6-4, 7-5, or 7-6 (tiebreak). Returns winner index (0|1) or -1.
function regularSetWinner(a, b) {
  const hi = Math.max(a, b);
  const lo = Math.min(a, b);
  const ok = (hi === 6 && lo <= 4) || (hi === 7 && (lo === 5 || lo === 6));
  return ok ? (a > b ? 0 : 1) : -1;
}

// Deciding match tiebreak: first to 10, win by 2.
function matchTiebreakWinner(a, b) {
  const hi = Math.max(a, b);
  const lo = Math.min(a, b);
  const ok = hi >= 10 && hi - lo >= 2 && (hi === 10 || hi - lo === 2);
  return ok ? (a > b ? 0 : 1) : -1;
}

/**
 * Validates tennis sets, e.g. [[6,4],[3,6],[10,7]] (each pair = [side0, side1] games).
 * A match tiebreak is only allowed as the deciding set. The match must be complete.
 * Returns setsWon / gamesWon (a match tiebreak counts as one set, its points not as games)
 * and `winner` (0|1|null).
 */
function validateTennisSets(sets, { bestOf = DEFAULT_TENNIS_BEST_OF } = {}) {
  const setsWon = [0, 0];
  const gamesWon = [0, 0];
  const fail = (code, extra) => ({ valid: false, errors: [err(code, extra)], setsWon, gamesWon, winner: null });
  if (bestOf !== 3 && bestOf !== 5) return fail('INVALID_BEST_OF');
  if (!Array.isArray(sets) || sets.length === 0) return fail('NO_SETS');
  if (sets.length > bestOf) return fail('TOO_MANY_SETS');
  const needed = Math.ceil(bestOf / 2);
  const errors = [];
  let winner = null;

  for (let i = 0; i < sets.length; i++) {
    const s = sets[i];
    if (!Array.isArray(s) || s.length !== 2 || !isNonNegInt(s[0]) || !isNonNegInt(s[1])) {
      return fail('INVALID_SET', { index: i });
    }
    if (winner !== null) return fail('SETS_AFTER_MATCH_END', { index: i });
    let w = regularSetWinner(s[0], s[1]);
    let isTiebreak = false;
    if (w === -1 && i === bestOf - 1) {
      w = matchTiebreakWinner(s[0], s[1]);
      isTiebreak = w !== -1;
    }
    if (w === -1) {
      errors.push(err('INVALID_SET_SCORE', { index: i }));
      continue;
    }
    setsWon[w] += 1;
    if (!isTiebreak) {
      gamesWon[0] += s[0];
      gamesWon[1] += s[1];
    }
    if (setsWon[w] >= needed) winner = w;
  }
  if (errors.length) return { valid: false, errors, setsWon, gamesWon, winner: null };
  if (winner === null) return fail('MATCH_INCOMPLETE');
  return { valid: true, errors: [], setsWon, gamesWon, winner };
}

/**
 * Validates a team result. Team sports: `{ scores: [home, away] }`. Tennis: `{ sets, bestOf? }`.
 * Returns `scores` (tennis: sets won) and `outcomes` ([WIN|LOSS|DRAW, ...]) per side.
 */
function validateResult(sport, result) {
  const invalid = (code) => ({ valid: false, errors: [err(code)], scores: [0, 0], outcomes: [] });
  if (!SPORT_KEYS.includes(sport)) return invalid('UNKNOWN_SPORT');
  if (!result || typeof result !== 'object') return invalid('INVALID_RESULT');
  if (sport === 'TENNIS') {
    const r = validateTennisSets(result.sets, { bestOf: result.bestOf });
    const outcomes = r.valid ? r.setsWon.map((s, i) => deriveOutcome(s, r.setsWon[1 - i])) : [];
    return { ...r, scores: r.setsWon, outcomes };
  }
  const { scores } = result;
  if (!Array.isArray(scores) || scores.length !== 2) return invalid('INVALID_SCORES');
  const errors = [];
  scores.forEach((s, index) => {
    if (!isNonNegInt(s)) errors.push(err(badNumberCode(s), { index }));
    else if (s > MAX_TEAM_SCORE[sport]) errors.push(err('TOO_LARGE', { index, max: MAX_TEAM_SCORE[sport] }));
  });
  if (errors.length) return { valid: false, errors, scores, outcomes: [] };
  return { valid: true, errors: [], scores, outcomes: scores.map((s, i) => deriveOutcome(s, scores[1 - i])) };
}

/**
 * Soft check: the players' recorded goals/points for a side should not exceed the side's
 * score (own goals and unrecorded scorers exist, so this is a warning, never an error).
 * `playerStats` = array of one side's per-player stat objects.
 */
function checkPlayerTotals(sport, teamScore, playerStats) {
  const key = SCORING_KEY[sport];
  if (!key) return [];
  const sum = (playerStats || []).reduce((acc, p) => acc + (isNonNegInt(p && p[key]) ? p[key] : 0), 0);
  return sum > teamScore ? [{ code: 'PLAYER_SUM_EXCEEDS_SCORE', key, sum, teamScore }] : [];
}

/** Sums `{ key, value }` entries per key. Entries with non-numeric values are ignored. */
function aggregateStats(entries) {
  const totals = {};
  for (const e of entries || []) {
    if (!e || typeof e.key !== 'string' || typeof e.value !== 'number' || !Number.isFinite(e.value)) continue;
    totals[e.key] = (totals[e.key] || 0) + e.value;
  }
  return totals;
}

module.exports = {
  STAT_DEFS,
  MAX_TEAM_SCORE,
  getStatDefs,
  getStatKeys,
  getSummaryKeys,
  getStatLabel,
  validateStats,
  deriveOutcome,
  validateTennisSets,
  validateResult,
  checkPlayerTotals,
  aggregateStats,
};
